def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = sum(1 for x in op if x == 'D')

    my_score = 0
    opp_score = 0
    for m, o in zip(my, op):
        if m == 'D':
            if o == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1
        else:
            if o == 'D':
                opp_score += 5
            else:
                my_score += 3
                opp_score += 3

    start = n - 10
    if start < 0:
        start = 0
    opp_def10 = sum(1 for i in range(start, n) if op[i] == 'D')

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            opp_c_streak += 1
        else:
            break

    coop_total = n - opp_def
    mostly_d = opp_def * 2 >= n
    bad = (
        (mostly_d and opp_def >= 3)
        or opp_def10 >= 8
        or (opp_def10 >= 7 and opp_def * 10 >= n * 5)
    )

    start_resp = n - 20
    if start_resp < 1:
        start_resp = 1

    tolerated = 0
    retaliated = 0
    for i in range(start_resp, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                tolerated += 1
            elif op[i] == 'D' and op[i - 1] == 'C':
                retaliated += 1

    last_my = my[-1]
    last_op = op[-1]

    if last_op == 'D':
        if opp_streak >= 7 or (opp_streak >= 5 and (coop_total < 5 or mostly_d)):
            return 'D'
        if last_my == 'D':
            return 'C'
        if opp_streak == 2:
            return 'D'
        return 'C'

    if last_my == 'D':
        if not bad and tolerated > 0 and tolerated >= retaliated - 1:
            return 'D'
    else:
        if not bad and tolerated > 0 and tolerated >= retaliated and opp_c_streak >= 2:
            return 'D'
        if bad and opp_def10 >= 6:
            return 'D'
        if n >= 90 and my_score < opp_score and rng.random() < 0.25:
            return 'D'

    return 'C'
